from pydantic import BaseModel, model_validator

class Item(BaseModel):
    name: str
    quantity: int
    price: float
    total: float = 0.0

    @model_validator(mode='after')
    def validate(self):
        self.total = self.quantity * self.price
        return self

for p in [dict(name='  book  ',quantity=3,price=2.5), dict(name='free',quantity=100,price=0)]:
    try:
        m = Item(**p)
        print(p, '->', m.total, type(m.total).__name__)
    except Exception as e:
        print(p, '-> ERROR:', type(e).__name__, str(e).splitlines()[-3] if str(e) else '')
